using System.Diagnostics;
using System.Text.Json;
namespace LeoLauncher;
sealed record WatchLink(string Name,string Url);
sealed class WatchLinkStore
{
    readonly string? path;public WatchLink[] Items{get;private set;}=Enumerable.Range(1,4).Select(i=>new WatchLink("观赛入口 "+i,"")).ToArray();
    public WatchLinkStore(string? file){path=file;try{if(file!=null){var saved=JsonSerializer.Deserialize<WatchLink[]>(File.ReadAllText(file));if(saved?.Length==4)Items=saved.Select((x,i)=>Normalize(x,i)).ToArray();}}catch{}}
    public static WatchLink Normalize(WatchLink item,int index){string name=item.Name?.Trim()??"";string url=item.Url?.Trim()??"";if(name.Length==0)name="观赛入口 "+(index+1);if(name.Length>18)throw new ArgumentException("名称最多18个字");if(url.Length>2048)throw new ArgumentException("网址太长");if(url.Length>0){if(!url.Contains("://"))url="https://"+url;if(!Uri.TryCreate(url,UriKind.Absolute,out var u)||u.Scheme is not("http" or "https")||u.UserInfo.Length>0)throw new ArgumentException("请填写有效的 http/https 网址");url=u.AbsoluteUri;}return new(name,url);}
    public void Save(IEnumerable<WatchLink> links){var next=links.Select(Normalize).ToArray();if(next.Length!=4)throw new ArgumentException("需要4个网址位置");if(path!=null){File.WriteAllText(path+".tmp",JsonSerializer.Serialize(next));File.Move(path+".tmp",path,true);}Items=next;}
}
sealed class WatchLinksPanel:Panel
{
    readonly WatchLinkStore store;readonly bool preview;readonly List<BarcaButton> links=new();
    public WatchLinksPanel(bool previewMode){preview=previewMode;store=new(preview?null:Path.Combine(Store.Root,"leo-watch-links.json"));Width=174;Height=238;Margin=new Padding(0,15,0,0);var title=new Label{Text="观赛网址",Bounds=new Rectangle(4,1,95,25),ForeColor=BarcaUi.Muted,Font=BarcaUi.Font(9)};var edit=new BarcaButton{Text="编辑",Bounds=new Rectangle(125,0,48,26)};edit.Click+=(_,_)=>Edit();Controls.Add(title);Controls.Add(edit);for(int i=0;i<4;i++){int index=i;var button=new BarcaButton{Bounds=new Rectangle(0,36+i*46,174,38)};button.Click+=(_,_)=>{if(store.Items[index].Url.Length==0){Edit();return;}if(!preview)try{Process.Start(FootTools.EdgeUrlStart(store.Items[index].Url));}catch(Exception e){UiDialogs.Show(FindForm(),e.Message,"Leo · 无法打开网址");}};links.Add(button);Controls.Add(button);}UpdateButtons();}
    void UpdateButtons(){for(int i=0;i<4;i++)links[i].Text=store.Items[i].Url.Length==0?"＋ 添加网址 "+(i+1):store.Items[i].Name+" ↗";}
    void Edit(){using var dialog=new Form{Text="Leo · 观赛网址",ClientSize=new Size(590,348),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,StartPosition=FormStartPosition.CenterParent,BackColor=BarcaUi.Canvas,ForeColor=BarcaUi.Text,Font=BarcaUi.Font(9)};var names=new List<TextBox>();var urls=new List<TextBox>();for(int i=0;i<4;i++){var n=new TextBox{Text=store.Items[i].Name,Bounds=new Rectangle(20,30+i*56,130,28),MaxLength=18};var u=new TextBox{Text=store.Items[i].Url,PlaceholderText=UiLanguage.T("粘贴比赛网址"),Bounds=new Rectangle(162,30+i*56,407,28),MaxLength=2048};foreach(var field in new[]{n,u}){field.BackColor=BarcaUi.Raised;field.ForeColor=BarcaUi.Text;field.BorderStyle=BorderStyle.FixedSingle;dialog.Controls.Add(field);}names.Add(n);urls.Add(u);}var error=new Label{Bounds=new Rectangle(20,263,540,29),ForeColor=Color.LightSalmon};dialog.Controls.Add(error);var save=new BarcaButton{Text="保存",Bounds=new Rectangle(478,300,90,31)};var cancel=new BarcaButton{Text="取消",Bounds=new Rectangle(376,300,90,31),DialogResult=DialogResult.Cancel};dialog.Controls.Add(save);dialog.Controls.Add(cancel);dialog.CancelButton=cancel;save.Click+=(_,_)=>{try{store.Save(Enumerable.Range(0,4).Select(i=>new WatchLink(names[i].Text,urls[i].Text)));dialog.DialogResult=DialogResult.OK;dialog.Close();}catch(Exception e){error.Text=e.Message;}};if(dialog.ShowDialog(FindForm())==DialogResult.OK)UpdateButtons();}
}
